-- Citation styles (citations.md, "The style"; the CI plan, CI-D and CI-E): an artifact kind of their own,
-- the tenant's as a prompt library is, in no space; CSE, Vancouver and Harvard seeded in every tenant,
-- unauthored at 0.1, under the domain's `SEEDED_CITATION_STYLES`; the citation catalogue's second
-- version, at catalogue/4, naming Harvard at that version; and the default theme's 0.9 naming it.
--
-- Each style's content is its CSL file as packages/domain/src/library/csl holds it, its name and
-- `SEEDED_REQUIRES`, canonicalised; the catalogue's and the theme's are the domain's `DEFAULT_CATALOGUES`
-- and `DEFAULT_THEME`. The content hashes and version digests the domain computes are written here as
-- literals for 0015's reason: citation-styles.test.ts and default-theme.test.ts recompute them.

set constraints all immediate;

alter table artifact drop constraint artifact_kind_check;
alter table artifact add constraint artifact_kind_check check (kind in
  ('component', 'document', 'publication', 'field', 'metadataSchema', 'componentType', 'layout',
   'asset', 'theme', 'catalogue', 'template', 'connection', 'queryDefinition', 'dataset', 'variable',
   'conditionAxis', 'relationshipType', 'prompt', 'promptLibrary', 'bibliographyEntry',
   'citationStyle'));

insert into artifact (id, kind, space_id)
select v.id::uuid, 'citationStyle', null
from (values
  ('a6c1e2f4-3b5d-4e7a-8c9b-1d2e3f4a5b6c'),
  ('b7d2f3a5-4c6e-4f8b-9dac-2e3f4a5b6c7d'),
  ('c8e3a4b6-5d7f-4a9c-8ebd-3f4a5b6c7d8e')
) as v (id)
on conflict (id) do nothing;

insert into artifact_version (
  id, artifact_id, kind, revision_no, version_no, author_id, note,
  schema_version, content, content_hash, metadata_values, not_carried,
  component_type_version_id, version_digest
)
select
  v.version::uuid, v.id::uuid, 'citationStyle', 0, 1, null, null,
  1, v.content::jsonb, v.content_hash, '{}'::jsonb, '[]'::jsonb,
  null, v.version_digest
