  ('c8e3a4b6-5d7f-4a9c-8ebd-3f4a5b6c7d8e', 'f3b6c9e4-8a0d-4d3f-9b5a-7c9e1a3d5f7b',
   $csl${"csl":"<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<style xmlns=\"http://purl.org/net/xbiblio/csl\" class=\"in-text\" version=\"1.0\" demote-non-dropping-particle=\"sort-only\" default-locale=\"en-US\">\n  <info>\n    <title>CSE Manual: Scientific Style and Format 9th edition (name-year)</title>\n    <title-short>Council of Science Editors SSF N-Y/author-date/Harvard</title-short>\n    <id>http://www.zotero.org/styles/cse-name-year</id>\n    <link href=\"http://www.zotero.org/styles/cse-name-year\" rel=\"self\"/>\n    <link href=\"http://www.zotero.org/styles/cse-citation-sequence\" rel=\"template\"/>\n    <link href=\"https://www.csemanual.org/Tools/CSE-Citation-Quick-Guide.html\" rel=\"documentation\"/>\n    <author>\n      <name>Patrick O'Brien</name>\n    </author>\n    <category citation-format=\"author-date\"/>\n    <category field=\"astronomy\"/>\n    <category field=\"biology\"/>\n    <category field=\"botany\"/>\n    <category field=\"chemistry\"/>\n    <category field=\"geology\"/>\n    <category field=\"medicine\"/>\n    <category field=\"science\"/>\n    <category field=\"zoology\"/>\n    <summary>Council of Science Editors style, 9th edition, name-year system: author-date in text, sorted alphabetically.</summary>\n    <updated>2025-09-12T07:37:16+00:00</updated>\n    <rights license=\"http://creativecommons.org/licenses/by-sa/3.0/\">This work is licensed under a Creative Commons Attribution-ShareAlike 3.0 License</rights>\n  </info>\n  <locale xml:lang=\"en\">\n    <terms>\n      <term name=\"editortranslator\" form=\"long\">\n        <single>editor and translator</single>\n        <multiple>editors and translators</multiple>\n      </term>\n      <term name=\"collection-editor\" form=\"long\">\n        <single>editor</single>\n        <multiple>editors</multiple>\n      </term>\n      <term name=\"in press\">published online ahead of print</term>\n    </terms>\n  </locale>\n  <macro name=\"editor\">\n    <names variable=\"editor translator\" delimiter=\"; \" suffix=\".\">\n      <name delimiter-precedes-last=\"always\" initialize-with=\"\" name-as-sort-order=\"all\" sort-separator=\" \"/>\n      <label prefix=\", \"/>\n    </names>\n  </macro>\n  <macro name=\"author\">\n    <names variable=\"author\" delimiter=\"; \">\n      <name name-as-sort-order=\"all\" sort-separator=\" \" initialize-with=\"\" delimiter=\", \" delimiter-precedes-last=\"always\"/>\n      <label form=\"long\" prefix=\", \" strip-periods=\"true\"/>\n      <substitute>\n        <names variable=\"editor translator\"/>\n        <text variable=\"title\"/>\n      </substitute>\n    </names>\n  </macro>\n  <macro name=\"author-short\">\n    <names variable=\"author\">\n      <name form=\"short\" delimiter=\", \" initialize-with=\".\" and=\"text\"/>\n      <substitute>\n        <names variable=\"editor\"/>\n        <names variable=\"translator\"/>\n        <text variable=\"title\" form=\"short\"/>\n      </substitute>\n    </names>\n  </macro>\n  <macro name=\"access\">\n    <group delimiter=\". \">\n      <group delimiter=\" \" prefix=\"[\" suffix=\"]\">\n        <text term=\"accessed\"/>\n        <date variable=\"accessed\" delimiter=\" \">\n          <date-part name=\"year\"/>\n          <date-part name=\"month\" form=\"short\" strip-periods=\"true\"/>\n          <date-part name=\"day\"/>\n        </date>\n      </group>\n      <text variable=\"URL\"/>\n    </group>\n  </macro>\n  <macro name=\"title\">\n    <group delimiter=\" \">\n      <text variable=\"title\"/>\n      <choose>\n        <if type=\"thesis\" match=\"any\">\n          <text variable=\"genre\" form=\"long\" prefix=\"[\" suffix=\"]\"/>\n        </if>\n      </choose>\n    </group>\n  </macro>\n  <macro name=\"publisher\">\n    <text variable=\"publisher\"/>\n  </macro>\n  <macro name=\"review\">\n    <group delimiter=\". \">\n      <text variable=\"reviewed-title\"/>\n      <text variable=\"container-title\"/>\n    </group>\n  </macro>\n  <macro name=\"pages\">\n    <group>\n      <label plural=\"never\" strip-periods=\"true\" suffix=\" \" variable=\"page\" form=\"short\"/>\n      <text variable=\"page\"/>\n    </group>\n  </macro>\n  <macro name=\"year-date\">\n    <date variable=\"issued\" form=\"numeric\" date-parts=\"year\"/>\n  </macro>\n  <macro name=\"date\">\n    <group delimiter=\" \">\n      <text macro=\"year-date\"/>\n      <choose>\n        <if type=\"patent article-newspaper webpage\" match=\"any\">\n          <date variable=\"issued\" delimiter=\" \">\n            <date-part name=\"month\" form=\"short\" strip-periods=\"true\"/>\n            <date-part name=\"day\"/>\n          </date>\n        </if>\n        <else-if type=\"article-journal article-magazine\" match=\"any\">\n          <choose>\n            <if variable=\"volume issue\" match=\"none\">\n              <date variable=\"issued\" delimiter=\" \">\n                <date-part name=\"month\" form=\"short\" strip-periods=\"true\"/>\n                <date-part name=\"day\"/>\n              </date>\n            </if>\n          </choose>\n        </else-if>\n      </choose>\n    </group>\n  </macro>\n  <macro name=\"edition\">\n    <choose>\n      <if is-numeric=\"edition\">\n        <group delimiter=\" \">\n          <number variable=\"edition\" form=\"ordinal\"/>\n          <text term=\"edition\" form=\"short\"/>\n        </group>\n      </if>\n      <else>\n        <text variable=\"edition\" suffix=\".\"/>\n      </else>\n    </choose>\n  </macro>\n  <macro name=\"collection\">\n    <choose>\n      <if type=\"report\">\n        <group prefix=\" \" suffix=\".\" delimiter=\" \">\n          <text variable=\"collection-title\"/>\n          <text variable=\"number\" prefix=\" Report No.: \"/>\n        </group>\n      </if>\n      <else>\n        <group prefix=\" (\" suffix=\").\" delimiter=\" \">\n          <names variable=\"collection-editor\" suffix=\". \">\n            <name delimiter-precedes-last=\"always\" initialize-with=\"\" name-as-sort-order=\"all\" sort-separator=\" \"/>\n            <label prefix=\", \"/>\n          </names>\n          <text variable=\"collection-title\"/>\n        </group>\n      </else>\n    </choose>\n  </macro>\n  <macro name=\"volume\">\n    <group delimiter=\" \">\n      <label text-case=\"capitalize-first\" strip-periods=\"true\" variable=\"volume\" form=\"short\"/>\n      <text variable=\"volume\"/>\n    </group>\n  </macro>\n  <citation et-al-min=\"3\" et-al-use-first=\"1\" disambiguate-add-year-suffix=\"true\" disambiguate-add-names=\"true\" disambiguate-add-givenname=\"true\">\n    <sort>\n      <key macro=\"year-date\"/>\n      <key macro=\"author-short\"/>\n    </sort>\n    <layout prefix=\"(\" suffix=\")\" delimiter=\"; \">\n      <group delimiter=\" \">\n        <text macro=\"author-short\"/>\n        <text macro=\"date\"/>\n      </group>\n      <text variable=\"locator\" prefix=\": \"/>\n    </layout>\n  </citation>\n  <bibliography et-al-min=\"5\" et-al-use-first=\"1\">\n    <sort>\n      <key macro=\"author\"/>\n      <key variable=\"issued\"/>\n    </sort>\n    <layout>\n      <text macro=\"author\" suffix=\".\"/>\n      <text macro=\"year-date\" prefix=\" \" suffix=\".\"/>\n      <choose>\n        <if type=\"bill book graphic legal_case legislation motion_picture report song thesis\" match=\"any\">\n          <group prefix=\" \" suffix=\".\" delimiter=\" \">\n            <text macro=\"title\" suffix=\".\"/>\n            <text macro=\"edition\"/>\n            <text macro=\"editor\"/>\n            <text macro=\"volume\"/>\n            <text macro=\"publisher\"/>\n            <text macro=\"pages\"/>\n          </group>\n        </if>\n        <else-if type=\"chapter paper-conference entry-dictionary entry-encyclopedia\" match=\"any\">\n          <text macro=\"title\" prefix=\" \" suffix=\".\"/>\n          <group prefix=\" \" delimiter=\" \">\n            <group delimiter=\" \">\n              <text term=\"in\" text-case=\"capitalize-first\" suffix=\":\"/>\n              <text macro=\"editor\"/>\n              <text variable=\"container-title\" suffix=\".\"/>\n            </group>\n            <group delimiter=\" \" suffix=\".\">\n              <label text-case=\"capitalize-first\" variable=\"volume\" form=\"short\"/>\n              <text variable=\"volume\"/>\n            </group>\n            <text macro=\"edition\"/>\n            <group prefix=\" \" delimiter=\"; \">\n              <text macro=\"publisher\"/>\n              <text macro=\"pages\"/>\n            </group>\n          </group>\n        </else-if>\n        <else-if type=\"review review-book\" match=\"any\">\n          <group suffix=\".\">\n            <text macro=\"title\" prefix=\" \"/>\n            <text macro=\"editor\" prefix=\" \"/>\n          </group>\n          <group prefix=\" \" suffix=\".\">\n            <text macro=\"review\" suffix=\".\"/>\n            <group>\n              <text variable=\"volume\"/>\n              <text variable=\"issue\" prefix=\"(\" suffix=\")\"/>\n            </group>\n            <text variable=\"page\" prefix=\":\"/>\n          </group>\n        </else-if>\n        <else-if type=\"webpage post post-weblog\" match=\"any\">\n          <text variable=\"container-title\" prefix=\" \" suffix=\";\"/>\n        </else-if>\n        <else>\n          <group suffix=\".\">\n            <text macro=\"title\" prefix=\" \"/>\n            <text macro=\"editor\" prefix=\" \"/>\n          </group>\n          <group delimiter=\". \" prefix=\" \">\n            <text variable=\"container-title\" form=\"short\" strip-periods=\"true\"/>\n            <choose>\n              <if match=\"none\" variable=\"volume page\">\n                <text term=\"in press\" prefix=\" [\" suffix=\"]\"/>\n              </if>\n              <else>\n                <group delimiter=\":\">\n                  <group>\n                    <text variable=\"volume\"/>\n                    <text variable=\"issue\" prefix=\"(\" suffix=\")\"/>\n                  </group>\n                  <text variable=\"page\"/>\n                </group>\n              </else>\n            </choose>\n          </group>\n        </else>\n      </choose>\n      <text prefix=\" \" macro=\"collection\"/>\n      <text prefix=\" \" macro=\"access\"/>\n      <text variable=\"DOI\" prefix=\". https://doi.org/\"/>\n    </layout>\n  </bibliography>\n</style>\n","name":"CSE","requires":{"article-journal":["title","container-title"],"book":["title"],"chapter":["title","container-title"],"paper-conference":["title"],"report":["title"],"thesis":["title"],"webpage":["title","URL"]},"schemaVersion":1}$csl$,
