-- The default theme's 0.9, unauthored, under the domain's `DEFAULT_THEME_VERSION`: 0.8 naming the
-- citation catalogue's second version, nothing else changed. Inserted only where the theme's latest
-- version is still 0064's own 0.8 - by its identifier and its content hash, unauthored - and nothing
-- after it, and the catalogue's second went in above. An environment that recorded a theme or a
-- citation catalogue of its own keeps it, and its documents cite in no style until one is named.
insert into artifact_version (
  id, artifact_id, kind, revision_no, version_no, author_id, note,
  schema_version, content, content_hash, metadata_values, not_carried,
  component_type_version_id, version_digest
)
